    "content": "36氪获悉，9月份，制造业采购经理指数、非制造业商务活动指数和综合PMI产出指数分别为50.1%、50.2%和50.7%，比上月上升0.3个、1.2个和1.2个百分点，经济景气水平有所回升。制造业生产指数为51.7%，比上月上升1.3个百分点，新订单指数为50.5%，比上月略降0.1个百分点，两个指数均高于临界点，制造业企业生产和市场需求继续改善。从行业看，农副食品加工、医药等行业生产指数和新订单指数均高于55.0%，相关企业产需释放较快；化学原料及化学制品、黑色金属冶炼及压延加工等行业生产指数和新订单指数均继续低…"
