    "pub_date": "2026-09-30 09:30:58",
    "author": "",
    "description": "36氪获悉，国家统计局数据显示,9月份，制造业采购经理指数（PMI）为50.1%，比上月上升0.3个百分点，升至扩张区间。从企业规模看，大型企业PMI为50.6%，与上月持平，高于临界点；中、小型企业PMI分别为49.7%和48.9%，比上月上升0.3个和1.0个百分点，均低于临界点。从分类指数看，构成制造业PMI的5个分类指数中，生产指数、新订单指数和供应商配送时间指数均高于临界点；原材料库存指数、从业人员指数低于临界点。生产指数为5…",
    "content": "36氪获悉，国家统计局数据显示,9月份，制造业采购经理指数（PMI）为50.1%，比上月上升0.3个百分点，升至扩张区间。从企业规模看，大型企业PMI为50.6%，与上月持平，高于临界点；中、小型企业PMI分别为49.7%和48.9%，比上月上升0.3个和1.0个百分点，均低于临界点。从分类指数看，构成制造业PMI的5个分类指数中，生产指数、新订单指数和供应商配送时间指数均高于临界点；原材料库存指数、从业人员指数低于临界点。生产指数为51.7%，比上月上升1.3个百分点，表明制造业生产活动扩张加快。"
