    "description": "中新网9月30日电 据自然资源部微信公众号消息，自2025年起，自然资源部和退役军人事务部组织集中攻坚开展烈士陵园不动产登记专项工作(以下简称“专项工作”)。经过一年多的努力，全国5439处烈士陵园(含烈士集中安葬墓区、烈士骨灰堂)全部完成登记发证，圆满实现“园园有证、权属清晰、四至明确”的目标。",
    "content": "中新网9月30日电 据自然资源部微信公众号消息，自2025年起，自然资源部和退役军人事务部组织集中攻坚开展烈士陵园不动产登记专项工作(以下简称“专项工作”)。经过一年多的努力，全国5439处烈士陵园(含烈士集中安葬墓区、烈士骨灰堂)全部完成登记发证，圆满实现“园园有证、权属清晰、四至明确”的目标。"
