    "title": "金与正：韩国借所谓地雷事件挑衅朝鲜",
    "link": "https://m.thepaper.cn/detail/34177030",
    "pub_date": "2026-09-30 08:57:59",
    "author": "王天僚/新华社客户端",
    "description": "据朝中社9月30日报道，朝鲜劳动党中央委员会部长金与正29日发表谈话说，近日，南部边境一带发生了一起地雷爆炸事件，韩国军方借此再次挑衅朝鲜。 金与正说，韩国把地雷爆炸事件的责任推卸给朝方，企图捏造“物证”来证明它，这种做法非常荒谬。 金与正警告，韩方将会为其挑衅行为承担责任。 据韩联社电视台21日援引韩国军方人士消息报道，韩国陆军第25师在韩朝军事分界线附近韩方一侧非军事区内执行任务过程中，发生疑似地雷爆炸事故，造成3人受伤，其中2人伤…",
    "content": "据朝中社9月30日报道，朝鲜劳动党中央委员会部长金与正29日发表谈话说，近日，南部边境一带发生了一起地雷爆炸事件，韩国军方借此再次挑衅朝鲜。 金与正说，韩国把地雷爆炸事件的责任推卸给朝方，企图捏造“物证”来证明它，这种做法非常荒谬。 金与正警告，韩方将会为其挑衅行为承担责任。 据韩联社电视台21日援引韩国军方人士消息报道，韩国陆军第25师在韩朝军事分界线附近韩方一侧非军事区内执行任务过程中，发生疑似地雷爆炸事故，造成3人受伤，其中2人伤势严重。韩国总统李在明29日要求军方迅速查明真相，并表示政府将视调查结果采取必要…"
