    "description": "2026年09月30日 本报北京9月29日电 （记者曲哲涵）29日，财政部会同中国人民银行、金融监管总局印发《关于实施居民购房贷款贴息政策的通知》，自今年10月1日起在全国范围内实施。 政策聚焦首套刚需，重点支持普通家庭新购中小套型、较低价位的住房，对同时符合以下条件的居民家庭给予贴息支持：一是使用新发放的商业性个人住房贷款购买首套住房，不包括存量贷款置换。其中，“首套住房”的认定按照现行政策执行，既包括新房也包括二手房。二是所购住房建…",
    "content": "2026年09月30日 本报北京9月29日电&nbsp;&nbsp;（记者曲哲涵）29日，财政部会同中国人民银行、金融监管总局印发《关于实施居民购房贷款贴息政策的通知》，自今年10月1日起在全国范围内实施。 政策聚焦首套刚需，重点支持普通家庭新购中小套型、较低价位的住房，对同时符合以下条件的居民家庭给予贴息支持：一是使用新发放的商业性个人住房贷款购买首套住房，不包括存量贷款置换。其中，“首套住房”的认定按照现行政策执行，既包括新房也包括二手房。二是所购住房建筑面积不超过120平方米。三是所购住房价格不超过150万元…"
