    "description": "2026年09月30日 本报北京9月29日电 （记者王观）国家税务总局最新数据显示：增值税留抵退税新政策实施一年来，全国累计办理留抵退税2818亿元。从退税资金流向来看，制造、科研、软件、生态等4个重点行业受益显著，累计享受留抵退税2120亿元，较新政策实施前同期增长10.4%；占全国留抵退税额的比例升至75.2%，较新政策实施前同期提高21.4个百分点，政策靶向支持效应充分释放。 2025年8月22日，财政部、国家税务总局发布公告，进…",
    "content": "2026年09月30日 本报北京9月29日电&nbsp;&nbsp;（记者王观）国家税务总局最新数据显示：增值税留抵退税新政策实施一年来，全国累计办理留抵退税2818亿元。从退税资金流向来看，制造、科研、软件、生态等4个重点行业受益显著，累计享受留抵退税2120亿元，较新政策实施前同期增长10.4%；占全国留抵退税额的比例升至75.2%，较新政策实施前同期提高21.4个百分点，政策靶向支持效应充分释放。 2025年8月22日，财政部、国家税务总局发布公告，进一步完善增值税期末留抵退税政策。去年9月起，我国对制造业、…"
