    "content": "2026年09月30日 新华社哈尔滨9月29日电&nbsp;&nbsp;（记者王鹤）29日，2026年青年普法志愿者法治文化基层行活动现场推进会在黑龙江省哈尔滨市召开。这一活动由中国法学会、司法部、共青团中央联合主办，自2008年5月开展以来，据不完全统计，累计组织1200万余名普法志愿者参与，开展线上线下普法活动1100万余场，受众人数达4亿人次。 据介绍，青年普法志愿者法治文化基层行活动持续组织动员广大青年普法志愿者深入基层一线，传播法律知识、弘扬法治精神、培育法治信仰，对推进法治社会建设起到重要作用。 中国法…"
