    "content": "2026年09月30日 不久前，财政部、税务总局、工业和信息化部联合发布公告，引起消费者关注：明年起，将取消节能汽车减半征收车船税政策，同时取消纯电动商用车、插电式（含增程式）混合动力汽车、燃料电池商用车的车船税免征优惠。政策调整的原因是什么？新能源汽车行业发展会不会因此“减速”？ 产业成熟，普惠式税惠政策具备适时退出的基础 读者关切：为什么要取消部分类型车辆的车船税减免政策？ 依据《中华人民共和国车船税法》及其实施条例，财政部、税务总局、工业和信息化部2012年发文明确：对符合条件的节能汽车减半征收车船税；对符合…"
