    "author": "",
    "description": "2026年09月30日 编者按：今年是中国工农红军长征胜利90周年。伟大长征精神是穿越时空的不朽丰碑，更是全民国防教育的鲜活教材。为让伟大长征精神代代相传，各地深入挖掘红色资源，广泛开展教育实践，在回望历史中厚植家国情怀，在缅怀先烈中赓续伟大长征精神。在烈士纪念日来临之际，本报记者走进三位在长征中牺牲英烈的故里，踏寻先辈足迹，传承红色基因，汲取奋进力量。 四川自贡市 “行走的思政课”上坚定信念 台上，四川自贡市大安区委党校副校长蒋婧姝声…",
    "content": "2026年09月30日 编者按：今年是中国工农红军长征胜利90周年。伟大长征精神是穿越时空的不朽丰碑，更是全民国防教育的鲜活教材。为让伟大长征精神代代相传，各地深入挖掘红色资源，广泛开展教育实践，在回望历史中厚植家国情怀，在缅怀先烈中赓续伟大长征精神。在烈士纪念日来临之际，本报记者走进三位在长征中牺牲英烈的故里，踏寻先辈足迹，传承红色基因，汲取奋进力量。 四川自贡市 “行走的思政课”上坚定信念 台上，四川自贡市大安区委党校副校长蒋婧姝声音微颤，讲述着红军英烈邓萍的事迹；台下，解放路中学的学生屏息凝神，思绪飘回那段血…"
