    "description": "2026年09月30日 2026年世界互联网大会乌镇峰会将于11月2日至5日在浙江乌镇举办，主题为“开源开放 共建共享——携手构建网络空间命运共同体”。9月29日，世界互联网大会国际组织在北京举行新闻发布会，介绍本次乌镇峰会的基本情况、亮点特色及筹备进展。 世界互联网大会秘书长任贤良介绍，本次峰会有以下特色亮点：聚焦开源开放，推动共建共享。本次峰会将邀请全球各界代表，围绕人工智能开源开放发展的理念与实践展开深入交流。峰会期间将举办系列活…",
    "content": "2026年09月30日 2026年世界互联网大会乌镇峰会将于11月2日至5日在浙江乌镇举办，主题为“开源开放&nbsp;&nbsp;共建共享——携手构建网络空间命运共同体”。9月29日，世界互联网大会国际组织在北京举行新闻发布会，介绍本次乌镇峰会的基本情况、亮点特色及筹备进展。 世界互联网大会秘书长任贤良介绍，本次峰会有以下特色亮点：聚焦开源开放，推动共建共享。本次峰会将邀请全球各界代表，围绕人工智能开源开放发展的理念与实践展开深入交流。峰会期间将举办系列活动，助力发展中国家汲取开源生态建设经验。紧扣前沿热点，创新…"
