    "content": "2026年09月30日 本报北京9月29日电&nbsp;&nbsp;（记者金歆）29日，由中国互联网络信息中心联合中国互联网协会、中国科学院计算机网络信息中心共同主办的2026（第七届）中国互联网基础资源大会在北京举行。与会嘉宾围绕“聚智向新、网筑未来”主题进行深入交流研讨。 会上发布了3项重要科研成果。资源公钥基础设施（RPKI）服务平台成果正式发布，充分展现了我国在RPKI体系建设领域的实践成效及在互联网路由安全领域的国际影响力。“智能体标识与安全保障技术北京市重点实验室”正式揭牌，重点布局智能体身份标识、可信…"
