    "description": "2026年09月30日 美国当地时间9月27日8时55分（北京时间9月27日20时55分），来自四川成都大熊猫繁育研究基地的大熊猫“平平”“福双”平安到达美国亚特兰大动物园，开启为期10年的旅居生活。中美双方将围绕大熊猫饲养繁育、疾病防治、科学研究、公众教育以及野外种群和栖息地保护等领域，进一步深化交流合作。 大熊猫是我国特有物种，也是世界生物多样性保护的珍稀物种、旗舰物种和明星物种。1994年以来，我国持续稳步开展大熊猫长期保护研究国…",
    "content": "2026年09月30日 美国当地时间9月27日8时55分（北京时间9月27日20时55分），来自四川成都大熊猫繁育研究基地的大熊猫“平平”“福双”平安到达美国亚特兰大动物园，开启为期10年的旅居生活。中美双方将围绕大熊猫饲养繁育、疾病防治、科学研究、公众教育以及野外种群和栖息地保护等领域，进一步深化交流合作。 大熊猫是我国特有物种，也是世界生物多样性保护的珍稀物种、旗舰物种和明星物种。1994年以来，我国持续稳步开展大熊猫长期保护研究国际合作，提升大熊猫保护研究能力和水平，增进中外人民了解与交流，为促进濒危物种保护…"
