    "content": "2026年09月30日 周五一下班，90后北京白领刘玲荣拉着行李箱直奔高铁站，去千里之外看一场演唱会。一张门票，带来两晚住宿、数顿餐饮和一次城市漫游。从为一场演出奔赴一座城，到跟着赛事、非遗打卡出游，越来越多群众愿意为体验、陪伴、情绪价值付费。 今年1—8月，社会消费商品和服务零售总额同比增长2.5%，其中服务零售额增长4.9%，快于商品零售额3.9个百分点，通讯信息服务类、旅游咨询租赁服务类、文体休闲服务类等服务消费增势突出。 服务消费“跑得更快”，折射出消费“换轨”大趋势——居民消费正从以商品消费为主，向商品消…"
